import{_ as d,a0 as n,w as o,s as l,ao as c,I as p,x as i,a1 as a,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"在你的 Fedora 终端上播放音乐 | LCTT x X-CMD","titleTemplate":false,"description":"在你的 Fedora 终端上播放音乐 | LCTT (202002) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在你的 Fedora 终端上播放音乐 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在你的 Fedora 终端上播放音乐 | LCTT (202002) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202002/20200210 Playing Music on your Fedora Terminal with MPD and ncmpcpp","title":"在你的 Fedora 终端上播放音乐","tag":"202002","desc":""},"relativePath":"202002/20200210 Playing Music on your Fedora Terminal with MPD and ncmpcpp.md","filePath":"[post].md"}'),r={name:"202002/20200210 Playing Music on your Fedora Terminal with MPD and ncmpcpp.md"};function h(g,e,u,m,k,f){const s=n("Link");return o(),l("div",null,[e[15]||(e[15]=c(`<h1 id="在你的-fedora-终端上播放音乐" tabindex="-1">在你的 Fedora 终端上播放音乐 <a class="header-anchor" href="#在你的-fedora-终端上播放音乐" aria-label="Permalink to “在你的 Fedora 终端上播放音乐”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2020/02/play_music_mpd-816x346.png" alt=""></p><p>MPD（Music Playing Daemon），顾名思义，是一个音乐（Music）播放（Playing）守护进程（Daemon）。它可以播放音乐，并且作为一个守护进程，任何软件都可以与之交互并播放声音，包括一些 CLI 客户端。</p><p>其中一个被称为 <code>ncmpcpp</code>，它是对之前 <code>ncmpc</code> 工具的改进。名字的变化与编写它们的语言没有太大关系：都是 C++，而之所以被称为 <code>ncmpcpp</code>，因为它是 “NCurses Music Playing Client Plus Plus”。 缘故</p><h3 id="安装-mpd-和-ncmpcpp" tabindex="-1">安装 MPD 和 ncmpcpp <a class="header-anchor" href="#安装-mpd-和-ncmpcpp" aria-label="Permalink to “安装 MPD 和 ncmpcpp”">​</a></h3><p><code>ncmpmpcc</code> 的客户端可以从官方 Fedora 库中通过 <code>dnf</code> 命令直接安装。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install ncmpcpp</span></span></code></pre></div><p>另一方面，MPD 必须从 RPMFusion free 库安装，你可以通过运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install https://download1.rpmfusion.org/free/fedora/rpmfusion-free-release-$(rpm -E %fedora).noarch.rpm</span></span></code></pre></div><p>然后你可以运行下面的命令安装它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install mpd</span></span></code></pre></div><h3 id="配置并启用-mpd" tabindex="-1">配置并启用 MPD <a class="header-anchor" href="#配置并启用-mpd" aria-label="Permalink to “配置并启用 MPD”">​</a></h3><p>设置 MPD 最简单的方法是以普通用户的身份运行它。默认情况是以专用 <code>mpd</code> 用户的身份运行它，但这会导致各种权限问题。</p><p>在运行它之前，我们需要创建一个本地配置文件，允许我们作为普通用户运行。</p><p>首先在 <code>~/.config</code> 里创建一个名叫 <code>mpd</code> 的目录:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir ~/.config/mpd</span></span></code></pre></div><p>将配置文件拷贝到此目录下:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cp /etc/mpd.conf ~/.config/mpd</span></span></code></pre></div><p>然后用 <code>vim</code>、<code>nano</code> 或 <code>gedit</code> 之类的软件编辑它:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ nano ~/.config/mpd/mpd.conf</span></span></code></pre></div><p>我建议你通读所有内容，检查是否有任何需要做的事情，但对于大多数设置你都可以删除，只需保留以下内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>db_file &quot;~/.config/mpd/mpd.db&quot;</span></span>
<span class="line"><span>log_file &quot;syslog&quot;</span></span></code></pre></div><p>现在你可以运行它了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mpd</span></span></code></pre></div><p>没有报错，这将在后台启动 MPD 守护进程。</p><h3 id="使用-ncmpcpp" tabindex="-1">使用 ncmpcpp <a class="header-anchor" href="#使用-ncmpcpp" aria-label="Permalink to “使用 ncmpcpp”">​</a></h3><p>只需运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ncmpcpp</span></span></code></pre></div><p>你将在终端中看到一个由 ncurses 所支持的图形用户界面。</p><p>按下 <code>4</code> 键，然后就可以看到本地的音乐目录，用方向键进行选择并按下回车进行播放。</p><p>多播放几个歌曲就会创建一个<em>播放列表</em>，让你可以使用 <code>&gt;</code> 键（不是右箭头, 是右尖括号）移动到下一首，并使用 <code>&lt;</code> 返回上一首。<code>+</code> 和 <code>–</code> 键可以调节音量。<code>Q</code> 键可以让你退出 <code>ncmpcpp</code> 但不停止播放音乐。你可以按下 <code>P</code> 来控制暂停和播放。</p><p>你可以按下 <code>1</code> 键来查看当前播放列表（这是默认的视图）。从这个视图中，你可以按 <code>i</code> 查看有关当前歌曲的信息（标签）。按 <code>6</code> 可更改当前歌曲的标签。</p><p>按 <code>\\</code> 按钮将在视图顶部添加（或删除）信息面板。在左上角，你可以看到如下的内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[------]</span></span></code></pre></div><p>按下 <code>r</code>、<code>z</code>、<code>y</code>、<code>R</code>、<code>x</code> 将会分别切换到 <code>repeat</code>、<code>random</code>、<code>single</code>、<code>consume</code> 和 <code>crossfade</code> 等播放模式，并将这个小指示器中的 <code>–</code> 字符替换为选定模式。</p><p>按下 <code>F1</code> 键将会显示一些帮助文档，包含一系列的键绑定列表，因此无需在此处列出完整列表。所以继续吧！做一个极客，在你的终端上播放音乐！</p><hr>`,37)),p("p",null,[e[1]||(e[1]=i("via: ",-1)),a(s,{href:"https://fedoramagazine.org/playing-music-on-your-fedora-terminal-with-mpd-and-ncmpcpp/"},{default:t(()=>[...e[0]||(e[0]=[i("https://fedoramagazine.org/playing-music-on-your-fedora-terminal-with-mpd-and-ncmpcpp/",-1)])]),_:1})]),p("p",null,[e[6]||(e[6]=i("作者：",-1)),a(s,{href:"https://fedoramagazine.org/author/carzacc/"},{default:t(()=>[...e[2]||(e[2]=[i("Carmine Zaccagnino",-1)])]),_:1}),e[7]||(e[7]=i(" 选题：",-1)),a(s,{href:"https://github.com/lujun9972"},{default:t(()=>[...e[3]||(e[3]=[i("lujun9972",-1)])]),_:1}),e[8]||(e[8]=i(" 译者：",-1)),a(s,{href:"https://github.com/chai-yuan"},{default:t(()=>[...e[4]||(e[4]=[i("chai-yuan",-1)])]),_:1}),e[9]||(e[9]=i(" 校对：",-1)),a(s,{href:"https://github.com/wxy"},{default:t(()=>[...e[5]||(e[5]=[i("wxy",-1)])]),_:1})]),p("p",null,[e[12]||(e[12]=i("本文由 ",-1)),a(s,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[10]||(e[10]=[i("LCTT",-1)])]),_:1}),e[13]||(e[13]=i(" 原创编译，",-1)),a(s,{href:"https://linux.cn/"},{default:t(()=>[...e[11]||(e[11]=[i("Linux中国",-1)])]),_:1}),e[14]||(e[14]=i(" 荣誉推出",-1))])])}const P=d(r,[["render",h]]);export{C as __pageData,P as default};
